"""A self-contained integrated review segment; supersedes no V1 artifact."""
VOICE=dict(voice='af_heart',speed=.74,lang='en-us',continuous=False,sentence_pause=.30,clause_pause=.12)
CODE=['int n; cin >> n;', 'vector<int> a(n);', 'for (int& x : a) cin >> x;', 'long long total = 0;', 'for (int i = 0; i < n; ++i) {', '    total += a[i];', '}', 'cout << total << "\\n";']
SCENES=[]
def add(key,title,text,mode='trace',i=None,total=None,highlight=None,note='',values=None,pause=.5):
 SCENES.append(dict(key=key,title=title,text=text,mode=mode,i=i,total=total,highlight=highlight,note=note,values=[3,-2,5,-1] if values is None else values,pause=pause))
add('story','THE TICKET DESK',"Rohail is helping Maya at their school music night. The cash box started empty, and his program reports eight dollars, but Maya counts only five. Before anyone launches a snack-table investigation, she asks him to check the receipts.",mode='story',note='Program: $8     Cash box: $5')
add('contract','READ EVERY RECEIPT',"Three dollars came in, two were refunded, another five came in, and one more was refunded. Rohail counted the payments but skipped the refunds. Eight is money received before refunds; their question asks how much remains. He needs a signed total.",mode='story',note='+3 -2 +5 -1     Include refunds')
add('input','THE COUNT IS NOT A PAYMENT',"There's no need for us to rush this through. Maya asks what the first input number means. Four tells the program how many transactions follow; it is not another payment. The next lines create four vector elements and read the signed values into them.",mode='input',highlight=2,note='Input: 4, then 3 -2 5 -1')
add('initialize','GIVE THE STATE A MEANING',"Rohail starts total at zero, using long long for the accumulated money. The loop starts its index at zero too. These variables happen to agree now, but they mean different things: the index is a position, and total is a balance.",i=0,total=0,highlight=3,note='Before the first condition check')
add('check0','CHECK BEFORE READING',"At the condition check, zero is less than four, so index zero is legal. Rohail points to the first receipt, positive three. Checking the condition gives permission to enter the body; it has not added the receipt yet.",i=0,total=0,highlight=4,note='0 < 4 is true; body has not run')
add('add0','ONE STATEMENT CHANGES THE BALANCE',"The highlighted addition reads that three and stores zero plus three in total. The balance is now three, while the index is still zero. Maya keeps her finger on the receipt: changing the balance does not secretly move to the next position.",i=0,total=3,highlight=5,note='Assignment: 0 + 3 = 3; i unchanged')
add('next1','MOVE, THEN CHECK AGAIN',"Only now does the increment move the index to one. One is less than four, so the next body execution is allowed. Its selected value is negative two, the refund that the first program ignored.",i=1,total=3,highlight=4,note='Increment to 1; then 1 < 4 is true')
add('add1','THE REFUND COUNTS TOO',"Rohail predicts that the balance should fall, and the addition confirms it: three plus negative two is one. Maya does not need a separate refund formula. The sign already tells this same statement which way the balance changes.",i=1,total=1,highlight=5,note='Assignment: 3 + (-2) = 1')
add('next2','KEEP THE ORDER OF EXECUTION',"The increment advances to index two, and two is less than four. The five-dollar payment is selected next. The stored balance is still one at this condition check, because the body has not processed that payment yet.",i=2,total=1,highlight=4,note='2 < 4 is true; total still 1')
add('add2','THE NEXT PAYMENT',"Adding five changes the balance from one to six. Rohail writes six in the total box and leaves the index at two until the increment runs. His trace follows the actual statements rather than changing every box at once.",i=2,total=6,highlight=5,note='Assignment: 1 + 5 = 6')
add('next3','THE LAST VALID POSITION',"The increment moves to three. Three is less than four, so there is one more valid body execution. Index three selects negative one, the final refund. Four elements have positions zero through three, not one through four.",i=3,total=6,highlight=4,note='3 < 4 is true; select -1')
add('add3','MATCH THE CASH BOX',"Six plus negative one gives five, matching the money Maya counted. Rohail wants to celebrate, but the program still has to finish its loop correctly. A correct balance does not give it permission to read beyond the vector.",i=3,total=5,highlight=5,note='Assignment: 6 + (-1) = 5')
add('stop','THE CHECK THAT STOPS THE LOOP',"The increment makes the index four. Four is less than four is false, so execution leaves the loop without reading an element at index four. Changing the condition to less than or equal would attempt an invalid extra read.",i=4,total=5,highlight=4,note='4 < 4 is false; no a[4] read')
add('output','PRINT THE REQUESTED ANSWER',"Now the output statement prints five and a newline. It prints the balance, not the index. The example works, but Maya asks whether tomorrow's different receipts would work too. That question takes us from checking one run to explaining the general rule.",i=4,total=5,highlight=7,note='Output: 5')
add('proof0','PROOF: START WITH NOTHING PROCESSED',"At every condition check, total should equal the sum of the first i values. This is our invariant. Initially, i is zero and total is zero, so the statement holds: the first zero values form an empty prefix with sum zero.",mode='proof',i=0,total=0,highlight=3,note='Initialization: sum of first 0 values = 0')
add('proofstep','PROOF: EXTEND THE PREFIX',"Suppose the invariant holds at a valid index k. The body adds the next value to the sum of the first k values, producing the sum of the first k plus one values. The increment then advances the index, restoring the invariant for the next check.",mode='proof',i='k',total='prefix(k)',highlight=5,note='Before: prefix(k)  →  after body: prefix(k+1)\nThen increment: i = k+1')
add('proofend','PROOF: STOP WITH EVERYTHING PROCESSED',"The index increases by one each iteration until it reaches the count. At that final check, the invariant says total is the sum of all n values, exactly our requested answer. The changing index also explains why the loop eventually stops.",mode='proof',i='n',total='prefix(n)',highlight=4,note='Termination: first n values = entire input')
add('empty','A REAL EMPTY-INPUT CASE',"Maya now supplies a count of zero, with no transactions after it. This is a new input, so the vector is empty and total starts at zero. The first check asks whether zero is less than zero; it is false. No element is read.",mode='trace',values=[],i=0,total=0,highlight=4,note='NEW INPUT: n = 0; 0 < 0 is false')
add('transfer','YOUR TURN — PAUSE THE VIDEO',"Try a fresh list: negative four, zero, seven and negative three. Record the index and balance before every condition check, including the final false check. Pause the video now to make your own trace; the next scene reveals the answer when you resume.",mode='question',values=[-4,0,7,-3],note='Write five condition-check states.\nLearner-controlled pause; answer on next scene.',pause=3)
add('answer','COMPARE YOUR TRACE',"The condition-check states are index zero with total zero, one with negative four, two with negative four, three with three, and four with zero. The zero transaction advanced the processed prefix without changing its sum. The correct final output is zero.",mode='answer',values=[-4,0,7,-3],note='(i, total): (0,0), (1,-4), (2,-4), (3,3), (4,0)')
add('cost','A SMALL PROGRAM WITH A GENERAL ARGUMENT',"The loop makes one addition per transaction, so its time is linear in the input count. This version stores a vector, using linear memory. Rohail now has more than a lucky five-dollar answer: he can trace a new input and explain why the same loop works.",mode='closing',note='Time O(n) · stored input O(n) · loop state O(1)')
